// Deterministic slalom rules shared by gameplay and save validation.
export const SKI_START={id:'ski-start',name:'Sonnenalp-Slalom starten',region:'hochalp',x:12,z:-8,range:2.3,ski:true};
export const SKI_LEVELS={easy:{name:'Gemütlich',speed:8,width:2.8,goal:8,reward:1000},normal:{name:'Sportlich',speed:10,width:2.3,goal:10,reward:1800},hard:{name:'Alpin',speed:12,width:1.9,goal:11,reward:2500}};
export const SKI_GATES=Array.from({length:12},(_,i)=>({distance:18+i*14,x:[0,-3.4,3.4,-2.6,3.4,-3.4,0,3.4,-3.4,2.6,-3.4,0][i]}));
export const SKI_FINISH=190;
export const freshSki=()=>({completed:[],best:{},runs:{easy:0,normal:0,hard:0},active:null});
export function atSkiStart(s){return s.position.region===SKI_START.region&&!s.position.inside&&!s.climbing.checkpoint&&Math.hypot(s.position.x-SKI_START.x,s.position.z-SKI_START.z)<2.8;}
export function startSki(s,level){if(!Object.hasOwn(SKI_LEVELS,level)||!atSkiStart(s)||s.ski.active)return{ok:false,message:'Gehe zuerst zum Slalomstart auf der Sonnenalp.'};if(s.energy<8)return{ok:false,message:'Für den Lauf brauchst du 8 Energie. Iss etwas oder raste in der Alphütte.'};s.energy-=8;s.ski.active={level,x:0,vx:0,distance:0,time:0,countdown:3,results:[],done:false};return{ok:true,message:'Ski und Helm sind bereit. Gleich geht es los!'};}
export function stepSki(c,dt,steer=0,brake=false){if(!c||c.done||!Number.isFinite(dt)||dt<0||dt>.1||!Number.isFinite(steer))return null;if(c.countdown>0){c.countdown=Math.max(0,c.countdown-dt);return null;}const level=SKI_LEVELS[c.level],old=c.distance,oldX=c.x;c.time+=dt;const desired=Math.max(-1,Math.min(1,steer))*7;c.vx+=(desired-c.vx)*Math.min(1,dt*9);c.x=Math.max(-8.5,Math.min(8.5,c.x+c.vx*dt));if(Math.abs(c.x)===8.5)c.vx=0;c.distance=Math.min(SKI_FINISH,c.distance+level.speed*(brake?.6:1)*dt);let event=null;while(c.results.length<SKI_GATES.length&&c.distance>=SKI_GATES[c.results.length].distance){const g=SKI_GATES[c.results.length],t=(g.distance-old)/(c.distance-old||1),x=oldX+(c.x-oldX)*t,hit=Math.abs(x-g.x)<=level.width;c.results.push(hit);event={type:hit?'gate':'miss',index:c.results.length-1};}if(c.distance>=SKI_FINISH){c.done=true;return{type:'finish'};}return event;}
export function skiScore(c){const level=SKI_LEVELS[c.level],hits=c.results.filter(Boolean).length;return Math.max(0,Math.min(1000,Math.round(hits/12*850+Math.max(0,150-Math.max(0,c.time-SKI_FINISH/level.speed)*6))));}
export function finishSki(s,exchange){const c=s.ski.active;if(!c?.done)return{ok:false,message:'Der Lauf ist noch nicht im Ziel.'};const level=SKI_LEVELS[c.level],hits=c.results.filter(Boolean).length,won=hits>=level.goal,score=skiScore(c),first=won&&!s.ski.completed.includes(c.level),reward=first?level.reward:0;const result=exchange(s,{earn:reward,stats:{earned:reward},reason:'challenge',ref:'ski-'+c.level});if(!result.ok)return result;s.ski.best[c.level]=Math.max(s.ski.best[c.level]||0,score);s.ski.runs[c.level]=Math.min(1000000,s.ski.runs[c.level]+1);if(first)s.ski.completed.push(c.level);s.ski.active=null;return{ok:true,won,score,hits,time:c.time,reward,level:c.level,message:won?'Slalom geschafft!':'Im Ziel. Für diese Stufe fehlen noch ein paar Tore.'};}
export function abandonSki(s){if(!s.ski.active)return{ok:false,message:'Kein aktiver Lauf.'};s.ski.active=null;return{ok:true,message:'Sicher zurück am Start. Für den Abbruch gibt es keine Prämie; Bestwerte bleiben erhalten.'};}
export function validSki(v,s){const obj=o=>o&&typeof o==='object'&&!Array.isArray(o),keys=Object.keys(SKI_LEVELS),n=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b,i=(x,a,b)=>Number.isSafeInteger(x)&&x>=a&&x<=b;if(!obj(v)||!Array.isArray(v.completed)||new Set(v.completed).size!==v.completed.length||!v.completed.every(k=>keys.includes(k))||!obj(v.best)||!Object.entries(v.best).every(([k,x])=>keys.includes(k)&&i(x,0,1000))||!obj(v.runs)||Object.keys(v.runs).length!==3||!keys.every(k=>i(v.runs[k],0,1000000))||!v.completed.every(k=>v.runs[k]>0&&Object.hasOwn(v.best,k)))return false;if(v.active===null)return true;const c=v.active;if(!obj(c)||!keys.includes(c.level)||!atSkiStart(s)||!n(c.x,-8.5,8.5)||!n(c.vx,-7,7)||!n(c.distance,0,SKI_FINISH)||!n(c.time,0,120)||!n(c.countdown,0,3)||!Array.isArray(c.results)||c.results.length!==SKI_GATES.filter(g=>g.distance<=c.distance).length||!c.results.every(x=>typeof x==='boolean')||typeof c.done!=='boolean'||c.done!==(c.distance===SKI_FINISH)||c.countdown>0&&(c.distance!==0||c.time!==0||c.x!==0||c.vx!==0))return false;return true;}
